def validate_orders(orders, min_total):
    valid = []
    for order in orders:
        if order is None:
            continue
        if "items" not in order or not order["items"]:
            continue
        if order.get("total", 0) < min_total:
            continue
        if order.get("status") == "cancelled":
            continue
        valid.append(order["id"])
    return valid

def export(records, compact, mode):
    """Export records in various formats."""
    def _csv(rec):
        if compact:
            return ",".join(str(v) for v in rec.values())
        return ", ".join(f"{k}={v}" for k, v in rec.items())

    def _json(rec):
        s = str(rec)
        return s.replace(" ", "") if compact else s

    def _keys(rec):
        if not rec:
            return ""
        if compact:
            return list(rec)[0]
        return "|".join(rec)

    exporters = {"csv": _csv, "json": _json, "keys": _keys}
    if mode not in exporters:
        raise ValueError("unknown mode")
    exporter = exporters[mode]
    return [exporter(r) for r in records]

def calculate_weighted_average_above_threshold(numbers, threshold, multiplier):
    """Return the rounded average of *multiplier*·value for all *value* in *numbers* that exceed *threshold*.

    The function mirrors the original behavior:
    * If *numbers* is empty, the result is ``0``.
    * The sum of qualifying values is divided by the original length of *numbers* (not the count of qualifying items).
    * The final result is rounded to two decimal places.
    """
    total = 0
    for value in numbers:
        if value > threshold:
            total += value * multiplier
    average = total / len(numbers) if numbers else 0
    return round(average, 2)

def parse_settings(lines):
    settings = {}
    for line in lines:
        # Skip non‑string lines, empty lines, and comments
        if not isinstance(line, str) or not line or line.startswith('#'):
            continue
        # Skip lines that don't contain an assignment
        if '=' not in line:
            continue
        key, value = line.split('=', 1)
        key = key.strip()
        val = value.strip()
        if val.isdigit():
            settings[key] = int(val)
        elif val.lower() in ('true', 'false'):
            settings[key] = val.lower() == 'true'
        else:
            settings[key] = val
    return settings

def _base_cost(weight: float, zone: int) -> float:
    zone_rates = {1: (4.99, 7.5), 2: (6.99, 10.25), 3: (9.5, 14.0), 4: (12.0, 18.75)}
    if zone not in zone_rates:
        return 25.0
    under2, over2 = zone_rates[zone]
    return under2 if weight < 2 else over2

def _surcharge(weight: float, cost: float) -> float:
    if weight > 20:
        return cost + 15
    if weight > 10:
        return cost + 7
    return cost

def _apply_express(cost: float, express: bool, zone: int) -> float:
    if not express:
        return cost
    multiplier = 1.5 if zone in (1, 2) else 2
    return cost * multiplier

def shipping_cost(weight: float, zone: int, express: bool) -> float:
    """Calculate shipping cost.

    Mirrors the original implementation exactly, including returning the
    integer ``0`` for non‑positive weights.
    """
    if weight <= 0:
        return 0  # Preserve original int return for non‑positive weight
    cost = _base_cost(weight, zone)
    cost = _surcharge(weight, cost)
    cost = _apply_express(cost, express, zone)
    return round(cost, 2)

def collect_tags(posts, seen=None):
    if seen is None:
        seen = []
    for post in posts:
        if not post:
            continue
        for tag in post.get("tags", []):
            if not tag:
                continue
            tag_lc = tag.lower()
            if tag_lc not in seen:
                seen.append(tag_lc)
    return seen

def is_eligible(age,income,student,veteran,state,score):
    if _young_eligible(age,income,student,veteran):
        if _state_score_eligible(state,score):
            return True
        if _score_income_veteran_eligible(score,income,veteran):
            return True
    if _senior_eligible(age,income):
        return score>500 or veteran
    return False

def _young_eligible(age,income,student,veteran):
    return (age>=18 and income<40000) or (student and age<26) or veteran

def _state_score_eligible(state,score):
    return state in ("NY","NJ") or (state=="CT" and score>600)

def _score_income_veteran_eligible(score,income,veteran):
    return (score>700 and income<60000) or (veteran and score>550)

def _senior_eligible(age,income):
    return (age>65 and income<30000) or age>70

def _grade_from_average(avg):
    if avg >= 90:
        return "A"
    if avg >= 80:
        return "B"
    if avg >= 70:
        return "C"
    return "F"

def grade_summary(math=None, science=None, english=None):
    out = {}
    subjects = {"math": math, "science": science, "english": english}
    for name, scores in subjects.items():
        if scores:
            avg = sum(scores) / len(scores)
            out[name] = _grade_from_average(avg)
    return out

def user_emails(users, domain):
    emails = []
    for user in users:
        # Preserve original behavior: raise KeyError if 'active' missing
        if not user["active"]:
            continue
        # Original only catches missing 'contact' key
        try:
            contact = user["contact"]
        except KeyError:
            continue
        # Preserve original key‑presence check
        if "email" not in contact:
            continue
        # Let any AttributeError (e.g., email is None) propagate as in the original
        email = contact["email"]
        if email.endswith(domain):
            emails.append(email.lower())
    return emails

def _format_value(value):
    if value is None:
        return ""
    if isinstance(value, str):
        return f'\"{value}\"' if ',' in value else value
    return str(value)

def to_csv(rows, columns):
    lines = [",".join(columns)]
    for row in rows:
        values = [_format_value(row.get(col)) for col in columns]
        lines.append(",".join(values))
    return "\n".join(lines) + "\n"

def nearest_points(points, origin, radius):
    """Return a list of unique points within *radius* of *origin*.
    *points* may contain ``None`` or items of unexpected length; such items are ignored.
    The function mirrors the original behavior while flattening nested conditionals.
    """
    found = []
    for p in points:
        # Guard clauses to keep the main logic at a shallow indentation level
        if p is None:
            continue
        if len(p) != 2:
            continue
        d = math.hypot(p[0] - origin[0], p[1] - origin[1])
        if d > radius:
            continue
        if p in found:
            continue
        found.append(p)
    return found

def restock(self, deliveries):
    added = 0
    for delivery in deliveries:
        if not delivery:
            continue
        for sku, qty in delivery.items():
            if qty <= 0:
                continue
            self.stock[sku] = self.stock.get(sku, 0) + qty
            added += qty
    return added
